SELECT
(SELECT COUNT(*) FROM group_order


        status = #{status}


) AS totalOrders,
(SELECT IFNULL(SUM(amount), 0) FROM group_order


        status = #{status}


) AS totalSales

SELECT order_no AS orderNo, user_id AS username, amount AS amount, status AS status, create_time AS createTime FROM group_order
status = #{status}
ORDER BY id DESC LIMIT 500
